const mk=(n:string,age:number)=>{const p=path.join(root,n);fs.mkdirSync(p);fs.writeFileSync(p+"/f","x");fs.utimesSync(p,age/1000,age/1000);};
mk("run-old",old); mk("run-young",Date.now()-60e3); mk("other-old",old); mk("run-old-file-inside",old);
fs.mkdirSync("/dev/shm/p6-target-"+process.pid); fs.writeFileSync("/dev/shm/p6-target-"+process.pid+"/keep","k"); fs.symlinkSync("/dev/shm/p6-target-"+process.pid, path.join(root,"run-x"));
